let textToSearch = "";
let isEmail = false;

// --- 1. DETECT THE SOURCE ---
if ($input.item.json.body && $input.item.json.body.data) {
    // It's a WhatsApp Message
    textToSearch = $input.item.json.body?.data?.message?.extendedTextMessage?.text 
                || $input.item.json.body?.data?.message?.conversation 
                || "";
} 
else if ($input.item.json.subject) {
    // It's an Email (Forwarded or Direct)
    isEmail = true;
    // Combine subject and body, and make it all lowercase for bulletproof searching
    textToSearch = ($input.item.json.subject + " " + ($input.item.json.textPlain || $input.item.json.text || "")).toLowerCase();
}

// --- 2. EXTRACT THE GOOGLE MEET LINK ---
const meetLinkMatch = textToSearch.match(/https:\/\/meet\.google\.com\/[a-z0-9-]+/i);

if (!meetLinkMatch) {
    return []; // Stops execution if no link is found
}

// --- 3. FILTER BY CLASS NAME (Only for Emails) ---
if (isEmail) {
    // Add the exact names of the classes you want to auto-attend here.
    // MUST BE IN ALL LOWERCASE because we convert the email text to lowercase above.
    const allowedClasses = [
        "devops a a",
        "scd lab fall 2025",
        "entrepreneurship bse a and b",
        "bsse 8a",
        "professional practices in it bse 8th a"
    ];

    // Check if the email text contains ANY of the allowed class names
    const isAllowedClass = allowedClasses.some(className => textToSearch.includes(className));

    if (!isAllowedClass) {
        // If the class isn't in your list, stop the workflow silently
        return []; 
    }
}

// --- 4. SUCCESS: PASS LINK TO PYTHON ---
return { url: meetLinkMatch[0] };

